import test from 'node:test';
import assert from 'node:assert/strict';
import {createWorkspace,submitPrompt,approveProject,deployProject,stopPrompt} from '../src/prototype-model.js';
test('school seed has complete teacher/class/student relationships and shared membership',()=>{const d=createWorkspace();assert.equal(d.teachers.length,20);assert.ok(d.classrooms.every(c=>d.teachers.some(t=>t.id===c.teacher)));assert.ok(d.students.every(s=>d.classrooms.some(c=>c.id===s.classroom)));assert.deepEqual(d.projects.find(p=>p.id==='teamspark').members,['alex','sam','jules']);});
test('unsafe prompts are blocked without charging or changing the project',()=>{const d=createWorkspace(),p=d.projects[0],balance=d.billing.credits,used=d.students[0].tokenUsed,result=submitPrompt(d,p,'Add my home address to the page');assert.equal(result.blocked,true);assert.equal(result.tokens,0);assert.equal(d.billing.credits,balance);assert.equal(d.students[0].tokenUsed,used);assert.equal(p.revision,1);assert.equal(d.prompts[0].status,'Blocked automatically');});
test('allowed prompts charge class/student/school and invalidate prior publishing approval',()=>{const d=createWorkspace(),p=d.projects[0];p.verification={revision:1};p.approval={revision:1};p.deployed=true;const result=submitPrompt(d,p,'Improve the hints');assert.equal(d.students[0].tokenUsed,4100+result.tokens);assert.equal(d.classrooms[0].tokenUsed,12500+result.tokens);assert.equal(d.billing.credits,120000-result.tokens);assert.equal(p.approval,null);assert.equal(p.verification,null);assert.equal(p.deployed,false);});
test('session, screen-time, account, held project and token limits prevent prompt charges',()=>{for(const mutate of [d=>d.classrooms[0].session='Paused',d=>d.students[0].screenUsed=45,d=>d.students[0].enabled=false,d=>d.projects[0].held=true,d=>d.students[0].tokenLimit=4100,d=>d.classrooms[0].tokenLimit=12500,d=>{d.billing.mode='Prepaid';d.billing.credits=0;}]){const d=createWorkspace();mutate(d);assert.ok(submitPrompt(d,d.projects[0],'Build a hint').error);assert.equal(d.prompts.length,8);assert.equal(d.projects[0].revision,1);}});
test('teacher can stop a queued prompt and hold the project without charging',()=>{const d=createWorkspace(),before=d.classrooms[0].tokenUsed;assert.equal(stopPrompt(d,'pending'),true);assert.equal(d.prompts.find(p=>p.id==='pending').status,'Stopped by teacher');assert.equal(d.projects.find(p=>p.id==='water').held,true);assert.equal(d.classrooms[0].tokenUsed,before);assert.equal(stopPrompt(d,'pending'),false);});
test('publication requires current verification, approval and school sharing permission',()=>{const d=createWorkspace(),p=d.projects[0];assert.ok(deployProject(p,d));p.verification={revision:1};p.status='Awaiting approval';assert.equal(approveProject(p),true);d.policies.studentSharing=false;assert.ok(deployProject(p,d));d.policies.studentSharing=true;assert.equal(deployProject(p,d),null);assert.equal(p.status,'Published');p.revision=2;assert.ok(deployProject(p,d));});
test('classmate projects cannot be edited by Alex',()=>{const d=createWorkspace();assert.match(submitPrompt(d,d.projects.find(p=>p.id==='water'),'Edit this').error,/read-only/);});
